// Local storage
function saveCartToLocalStorage() {
    localStorage.setItem('cart', JSON.stringify(cart));
}

function loadCartFromLocalStorage() {
    const saved = localStorage.getItem('cart');
    if (saved) {
        cart = JSON.parse(saved);
        updateCart();
    }
}

// Setup event listeners
function setupEventListeners() {
    closeBtn.addEventListener('click', closeModal);

    window.addEventListener('click', (event) => {
        if (event.target === modal) {
            closeModal();
        }
    });

    // Explore button
    document.getElementById('exploreBtn').addEventListener('click', () => {
        document.getElementById('featuredProducts').scrollIntoView({ behavior: 'smooth' });
    });

    // Newsletter form
    document.getElementById('newsletterForm').addEventListener('submit', (e) => {
        e.preventDefault();
        const email = e.target.querySelector('input[type="email"]').value;
        showNotification(`Thanks for subscribing with ${email}!`);
        e.target.reset();
    });

    // Search functionality
    const searchBox = document.querySelector('.search-box');
    searchBox.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            showNotification(`Searching for "${e.target.value}"...`);
            e.target.value = '';
        }
    });

    // Cart button
    document.querySelector('.cart-btn').addEventListener('click', () => {
        if (cart.length === 0) {
            showNotification('Your cart is empty');
        } else {
            const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
            showNotification(`Cart Total: $${total.toFixed(2)} (${cart.reduce((sum, item) => sum + item.quantity, 0)} items)`);
        }
    });
}
