    width: 100%;
    height: 280px;
    background: linear-gradient(135deg, #e0e7ff 0%, #f3e8ff 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    position: relative;
    overflow: hidden;
}

.product-image::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(99, 102, 241, 0.05);
    transition: var(--transition);
}

.product-card:hover .product-image::after {
    background: rgba(99, 102, 241, 0.15);
}

.product-badge {
    position: absolute;
    top: 12px;
    right: 12px;
    background-color: var(--accent-color);
    color: white;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    z-index: 1;
}

.product-info {
    padding: 1.5rem;
}

.product-category {
