}

.deal-card::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -50%;
    width: 200px;
    height: 200px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 50%;
    transition: var(--transition);
}

.deal-card:hover::before {
    transform: translate(20px, 20px);
}

.deal-content {
    position: relative;
    z-index: 1;
}

.deal-tag {
    display: inline-block;
    background-color: rgba(255, 255, 255, 0.2);
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    font-size: 0.8rem;
    margin-bottom: 1rem;
    backdrop-filter: blur(10px);
}

.deal-title {
    font-size: 1.75rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.deal-description {
    font-size: 0.95rem;
    opacity: 0.95;
    margin-bottom: 1.5rem;
}

.deal-discount {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.deal-btn {
    background-color: white;
    color: var(--secondary-color);
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
}

.deal-btn:hover {
    transform: scale(1.05);
}

/* Editorial Section */
.editorial-section {
    background-color: var(--light-bg);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background: white;
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.editorial-card:hover {
