    text-align: center;
    padding: 4rem 2rem !important;
    border-radius: 8px;
    margin: 2rem auto;
}

.newsletter-section h2 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.newsletter-section p {
    margin-bottom: 2rem;
    opacity: 0.95;
}

.newsletter-form {
    display: flex;
    gap: 1rem;
    max-width: 500px;
    margin: 0 auto;
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 250px;
